
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_x_cam_s12g_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_x_cam_s12g", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.036124349173218e+00, -3.951427537525198e+00, -3.833024146440381e+00, -3.669620139878762e+00, -3.448351233681110e+00, -3.157064035928560e+00, -2.789490214934254e+00, -2.353373231728845e+00, -1.872233245413007e+00, -1.363333641777834e+00, -8.548479577250517e-01, -5.322099432792627e-01, -4.440554824642512e-01, -3.544026762938800e-01, -2.572088220359011e-01, -1.686009870643944e-01, -8.907803567141383e-02, -3.183771362290106e-02, -6.901454604372229e-03, -7.760389690046431e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


